package Lecture1;

public class GreaterOF2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 10;
		int b = 20;
		
		if(a>b) {
			System.out.println(a);
		}
		else if(a==b) {
			System.out.println("equal");
		}
		else {
			System.out.println(b);
		}
		
	}

}
